package transport

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"errors"

	"itom.local/core/journal"
	"itom.local/core/pool"
	"itom.local/core/secure"
	"itom.local/core/wallet"
	"itom.local/core/wire"
)

var ErrInvitationUsed = errors.New("V2_INVITATION_ALREADY_USED")

// InvitationTemplate pins the profile and a freshly client-chosen Session.
// Session MUST come from an authenticated request, never an old invitation or
// provider hint. Handshake is zero here and generated by the issuer's CSPRNG.
type InvitationTemplate struct {
	Binding    secure.Binding
	Generation uint64
}

// PrepareSessionInvitation reserves a real initial remote CONTROL grant and
// publishes its offer in another locally charged CONTROL attempt. A successful
// call is not an APPEND: the authority owner retains/starts the exact returned
// publication. If any subsequent step fails, the remote allocation remains in
// the original journal and must be recovered by ScanGrants, never reissued as
// if it had not committed. This does not implement rotation/READY/reclamation.
func PrepareSessionInvitation(ctx context.Context, store *journal.Store, template InvitationTemplate, account, folder string, validity uint32, allowance pool.Amount, key []byte) (*PreparedPublication, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	if store == nil || template.Generation == 0 || template.Binding.Session == (wire.ID{}) || template.Binding.Handshake != (wire.ID{}) || len(key) != 32 || validity == 0 || allowance.Messages < 3 {
		return nil, ErrProtocol
	}
	binding := template.Binding
	if _, err := rand.Read(binding.Handshake[:]); err != nil {
		return nil, err
	}
	if _, err := secure.NewSessionHandshake(binding, key, false); err != nil {
		return nil, err
	}
	origin := ServerOrigin{Store: store.StoreID(), Run: store.Run(), Account: account, User: binding.User, Folder: folder, UIDValidity: validity}
	shape := wire.QuotaKey{Store: origin.Store, Epoch: origin.Run, Grant: 1, Session: binding.Session, Account: account, User: binding.User}
	if _, err := wire.ServerEnvelopeSize(shape, wire.ServerControl, folder, 1); err != nil {
		return nil, ErrProtocol
	}
	grant, err := store.IssueInitialRemote(journal.Scope{Account: account, User: binding.User, Session: binding.Session}, allowance)
	if err != nil {
		return nil, err
	}
	offer, err := store.RemoteOffer(grant.Ref)
	if err != nil {
		return nil, err
	}
	control, err := wire.EncodeControl(0, offer)
	if err != nil {
		return nil, err
	}
	raw, err := control.MarshalBinary()
	if err != nil {
		return nil, err
	}
	packet, err := encodeSessionFrame("ISI2", bootstrapFrame{binding: binding, generation: template.Generation, payload: raw})
	clear(raw)
	if err != nil {
		return nil, err
	}
	defer clear(packet)
	return prepareControlPacket(ctx, store, origin, binding.Session, packet, key)
}

// VerifiedInvitation can only be constructed from a full actual selected BODY
// with profile-key MAC, canonical charge, profile binding, ledger and scope
// validation. It contains no private key, DATA allowance or refund authority.
type VerifiedInvitation struct {
	binding    secure.Binding
	generation uint64
	origin     ServerOrigin
	offer      wire.StorageGrant
	uid        uint32
	anchorUID  uint32
	keyHash    [32]byte
	issuer     *journal.Store
}

func (v *VerifiedInvitation) Context() secure.Binding { return v.binding }

func verifySessionInvitation(executor *Executor, physical Body, expected InvitationTemplate, key []byte) (*VerifiedInvitation, mailboxEnvelope, error) {
	if executor == nil || executor.account == "" || executor.mailbox == "" || executor.validity == 0 || physical.UID == 0 || physical.Sequence == 0 || len(key) != 32 || expected.Binding.Session == (wire.ID{}) || expected.Binding.Handshake != (wire.ID{}) || expected.Generation == 0 {
		return nil, mailboxEnvelope{}, ErrProtocol
	}
	e, err := openMailboxEnvelope(physical.Bytes, key)
	if err != nil {
		return nil, e, err
	}
	f, err := decodeSessionFrame(e.packet, "ISI2")
	if err != nil {
		return nil, e, err
	}
	if f.kind != 0 || f.generation != expected.Generation || e.class != wire.ServerControl || e.usage.Attempt == nil {
		return nil, e, ErrProtocol
	}
	identity := f.binding
	identity.Handshake = wire.ID{}
	if identity != expected.Binding || e.usage.Key.Account != executor.account || e.usage.Key.User != f.binding.User || e.usage.Key.Session != f.binding.Session || e.usage.Attempt.Folder != executor.mailbox {
		return nil, e, ErrProtocol
	}
	if _, err = secure.NewSessionHandshake(f.binding, key, true); err != nil {
		return nil, e, err
	}
	frame, err := wire.ParseFrame(f.payload)
	if err != nil || frame.Stream != 0 {
		return nil, e, ErrProtocol
	}
	message, err := wire.DecodeControl(frame)
	if err != nil {
		return nil, e, err
	}
	offer, ok := message.(wire.StorageGrant)
	if !ok || offer.Key.Store != e.usage.Key.Store || offer.Key.Epoch != e.usage.Key.Epoch || offer.Key.Session != f.binding.Session || offer.Key.User != f.binding.User || offer.Key.Account != executor.account || offer.Limit.Messages < 3 || offer.Limit.Bytes == 0 {
		return nil, e, ErrProtocol
	}
	v := &VerifiedInvitation{binding: f.binding, generation: f.generation, origin: ServerOrigin{Store: offer.Key.Store, Run: offer.Key.Epoch, Account: executor.account, User: f.binding.User, Folder: executor.mailbox, UIDValidity: executor.validity}, offer: offer, uid: physical.UID, keyHash: sha256.Sum256(key)}
	return v, e, nil
}

func VerifySessionInvitation(executor *Executor, physical Body, expected InvitationTemplate, key []byte) (*VerifiedInvitation, error) {
	v, e, err := verifySessionInvitation(executor, physical, expected, key)
	clear(e.body)
	return v, err
}

// ObserveSessionInvitation additionally proves this issuer's own stored intent.
// Matching a marker/UID or a client MAC cannot substitute for this full proof.
func ObserveSessionInvitation(store *journal.Store, executor *Executor, physical Body, expected InvitationTemplate, key []byte) (*VerifiedInvitation, error) {
	v, e, err := verifySessionInvitation(executor, physical, expected, key)
	defer clear(e.body)
	if err != nil {
		return nil, err
	}
	if store == nil || store.StoreID() != v.origin.Store || store.Run() != v.origin.Run {
		return nil, ErrProtocol
	}
	ref, err := store.LocalAttempt(e.usage.Key, e.usage.Attempt.Batch)
	if err != nil {
		return nil, err
	}
	err = store.Observe(ref, store.Run(), journal.Observation{Account: v.origin.Account, Folder: v.origin.Folder, EncodedBytes: e.charge, Location: journal.Location{UIDValidity: executor.validity, UID: physical.UID}, Decoded: e.body})
	if err != nil {
		return nil, err
	}
	v.issuer = store
	return v, nil
}

// NewClient accepts an actual offer only into the freshly opened requesting
// wallet. It never creates/resumes a session from an invitation. A reinstalled
// client chooses another random Session, so an old invitation cannot reset its
// original writer counters even when that client's wallet history is missing.
func (v *VerifiedInvitation) NewClient(w *wallet.Wallet, key []byte) (*SessionBootstrap, error) {
	if v == nil || w == nil || len(key) != 32 || v.keyHash != sha256.Sum256(key) {
		return nil, ErrProtocol
	}
	identity := w.Identity()
	if identity.Session != v.binding.Session || identity.Store != v.origin.Store || identity.User != v.origin.User {
		return nil, ErrProtocol
	}
	if err := w.Accept(v.offer); err != nil {
		return nil, err
	}
	b, err := NewClientSessionBootstrap(v.binding, v.generation, w, v.origin, key)
	if err != nil {
		return nil, err
	}
	b.knownUIDs[v.uid] = true
	if v.anchorUID != 0 {
		b.knownUIDs[v.anchorUID] = true
	}
	return b, nil
}

func (v *VerifiedInvitation) NewServer(store *journal.Store, key []byte) (*SessionBootstrap, error) {
	if v == nil || store == nil || v.issuer != store || len(key) != 32 || v.keyHash != sha256.Sum256(key) || store.StoreID() != v.origin.Store || store.Run() != v.origin.Run {
		return nil, ErrProtocol
	}
	ref := journal.GrantRef{Store: v.offer.Key.Store, ID: v.offer.Key.Grant, Scope: journal.Scope{Account: v.offer.Key.Account, User: v.offer.Key.User, Session: v.offer.Key.Session}}
	offer, err := store.RemoteOffer(ref)
	if err != nil || offer != v.offer {
		return nil, errors.Join(ErrProtocol, err)
	}
	b, err := NewServerSessionBootstrap(v.binding, v.generation, store, v.origin.Account, v.origin.Folder, v.origin.UIDValidity, key)
	if err != nil {
		return nil, err
	}
	if err = store.ClaimUnusedRemoteSession(ref); err != nil {
		b.Close()
		if errors.Is(err, journal.ErrState) {
			return nil, ErrInvitationUsed
		}
		return nil, err
	}
	b.knownUIDs[v.uid] = true
	if v.anchorUID != 0 {
		b.knownUIDs[v.anchorUID] = true
	}
	return b, nil
}
